<?php
declare(strict_types=1);require_once __DIR__.'/marketplace-transaction.php';

function request_manager(array $user):bool{return in_array($user['role'],['OWNER_ADMIN','ADMIN','SUPERVISOR'],true);}
function request_expire():void{db()->exec("UPDATE marketplace_requests SET status='EXPIRED',expired_at=UTC_TIMESTAMP() WHERE status IN ('OPEN','RESPONSES_RECEIVED') AND response_deadline<=UTC_TIMESTAMP()");db()->exec("UPDATE supply_offers o JOIN marketplace_requests r ON r.id=o.request_id JOIN supply_offer_versions v ON v.supply_offer_id=o.id AND v.version_number=o.current_version SET o.status='EXPIRED' WHERE o.status IN ('SUBMITTED','VIEWED') AND (v.validity_until IS NOT NULL AND v.validity_until<=UTC_TIMESTAMP() OR r.status='EXPIRED')");}
function request_event(string $id,?array $user,string $event,array $data=[]):void{db()->prepare('INSERT INTO request_events(request_id,actor_user_id,event_type,event_data) VALUES(?,?,?,?)')->execute([$id,$user['id']??null,$event,$data?json_encode($data,JSON_THROW_ON_ERROR):null]);if($user)operation_audit($user,'request.'.strtolower($event),'request',$id,null,$data);}
function request_record(array $user,string $id,bool $lock=false):array{$row=rows("SELECT r.*,o.name requester_name,t.name equipment_type,c.name category_name,sc.name subcategory_name,loc.canonical_name location_name,loc.country_name FROM marketplace_requests r JOIN owners o ON o.id=r.organization_id JOIN equipment_types t ON t.id=r.equipment_type_id LEFT JOIN equipment_categories c ON c.id=r.category_id LEFT JOIN equipment_subcategories sc ON sc.id=r.subcategory_id JOIN marketplace_locations loc ON loc.id=r.required_location_id WHERE r.id=?".($lock?' FOR UPDATE':''),[$id])[0]??null;if(!$row)throw new DomainException('Equipment request not found.',404);if($row['organization_id']!==$user['owner_id']&&$row['visibility']!=='PUBLIC')throw new DomainException('You do not have access to this private request.',403);return $row;}
function request_owned(array $user,string $id,bool $lock=false):array{$r=request_record($user,$id,$lock);if($r['organization_id']!==$user['owner_id']||!request_manager($user))throw new DomainException('You cannot manage this request.',403);return $r;}
function request_public(string $id):array{request_expire();$row=rows("SELECT r.*,o.name requester_name,o.marketplace_verified,t.name equipment_type,c.name category_name,sc.name subcategory_name,loc.canonical_name location_name,loc.country_name FROM marketplace_requests r JOIN owners o ON o.id=r.organization_id JOIN equipment_types t ON t.id=r.equipment_type_id LEFT JOIN equipment_categories c ON c.id=r.category_id LEFT JOIN equipment_subcategories sc ON sc.id=r.subcategory_id JOIN marketplace_locations loc ON loc.id=r.required_location_id WHERE r.id=? AND r.visibility='PUBLIC' AND r.status IN ('OPEN','RESPONSES_RECEIVED') AND r.response_deadline>UTC_TIMESTAMP()",[$id])[0]??null;if(!$row)throw new DomainException('This equipment request is no longer available.',404);return $row;}
function request_snapshot(array $r):array{foreach(['requester_name','equipment_type','category_name','subcategory_name','location_name','country_name'] as $key)unset($r[$key]);return $r;}
function request_specs(string $text):array{$result=[];foreach(preg_split('/\R/',trim($text)) as $line){$line=trim($line);if($line==='')continue;[$key,$value]=array_pad(array_map('trim',explode(':',$line,2)),2,'');if($value===''){$key='Requirement '.(count($result)+1);$value=$line;}$result[mb_substr($key,0,120)]=mb_substr($value,0,500);}return $result;}
function request_payload(array $input):array{$intent=marketplace_enum($input,'intent',['LEASE','PURCHASE','EITHER']);$from=marketplace_text($input,'required_from',10,true);$until=marketplace_text($input,'required_until',10);if(in_array($intent,['LEASE','EITHER'],true)&&(!$until||$until<$from))throw new DomainException('Add a valid required-until date for a lease request.',422);$deadline=str_replace('T',' ',marketplace_text($input,'response_deadline',16,true)).':00';if($deadline<=gmdate('Y-m-d H:i:s'))throw new DomainException('Response deadline must be in the future.',422);if($from<gmdate('Y-m-d'))throw new DomainException('Required-from date cannot be in the past.',422);$type=marketplace_text($input,'equipment_type_id',36,true);if(!rows('SELECT 1 FROM equipment_types WHERE id=?',[$type]))throw new DomainException('Choose a valid equipment type.',422);$location=marketplace_text($input,'required_location_id',36,true);if(!rows('SELECT 1 FROM marketplace_locations WHERE id=?',[$location]))throw new DomainException('Choose a valid required location.',422);return ['equipment_type_id'=>$type,'category_id'=>marketplace_text($input,'category_id',36)?:null,'subcategory_id'=>marketplace_text($input,'subcategory_id',36)?:null,'title'=>marketplace_text($input,'title',255,true),'description'=>marketplace_text($input,'description',5000,true),'intent'=>$intent,'quantity_required'=>max(1,(int)($input['quantity_required']??1)),'required_location_id'=>$location,'required_from'=>$from,'required_until'=>$until?:null,'response_deadline'=>$deadline,'visibility'=>marketplace_enum($input,'visibility',['PRIVATE','PUBLIC'],'PUBLIC'),'alternatives_accepted'=>!empty($input['alternatives_accepted'])?1:0,'core_specifications'=>json_encode(request_specs((string)($input['core_specifications']??'')),JSON_THROW_ON_ERROR),'required_documents'=>marketplace_text($input,'required_documents',5000),'oem_preference'=>marketplace_text($input,'oem_preference',255),'model_preference'=>marketplace_text($input,'model_preference',255)];}
function request_save_requirements(string $id,array $specs):void{db()->prepare('DELETE FROM request_requirements WHERE request_id=?')->execute([$id]);$stmt=db()->prepare("INSERT INTO request_requirements(id,request_id,attribute_key,required_value,comparison_operator,requirement_level) VALUES(?,?,?,?,NULL,'MANDATORY')");foreach($specs as $key=>$value)$stmt->execute([uuid(),$id,$key,json_encode($value,JSON_THROW_ON_ERROR)]);}
function request_create(array $user,array $input,bool $publish):string{if(!request_manager($user))throw new DomainException('Your role cannot create sourcing requests.',403);$p=request_payload($input);$id=uuid();db()->prepare('INSERT INTO marketplace_requests(id,requester_user_id,organization_id,equipment_type_id,category_id,subcategory_id,title,description,intent,quantity_required,required_location_id,required_from,required_until,response_deadline,visibility,alternatives_accepted,core_specifications,required_documents,oem_preference,model_preference,status,published_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$user['id'],$user['owner_id'],$p['equipment_type_id'],$p['category_id'],$p['subcategory_id'],$p['title'],$p['description'],$p['intent'],$p['quantity_required'],$p['required_location_id'],$p['required_from'],$p['required_until'],$p['response_deadline'],$p['visibility'],$p['alternatives_accepted'],$p['core_specifications'],$p['required_documents'],$p['oem_preference'],$p['model_preference'],$publish?'OPEN':'DRAFT',$publish?gmdate('Y-m-d H:i:s'):null]);request_save_requirements($id,json_decode($p['core_specifications'],true));$r=rows('SELECT * FROM marketplace_requests WHERE id=?',[$id])[0];db()->prepare('INSERT INTO marketplace_request_versions(id,request_id,version_number,snapshot,created_by) VALUES(?,?,1,?,?)')->execute([uuid(),$id,json_encode(request_snapshot($r),JSON_THROW_ON_ERROR),$user['id']]);request_event($id,$user,$publish?'PUBLISHED':'DRAFT_CREATED');return $id;}
function request_update(array $user,string $id,array $input):void{$r=request_owned($user,$id,true);if(!in_array($r['status'],['DRAFT','OPEN'],true))throw new DomainException('This request can no longer be edited.',409);$responses=(int)(rows("SELECT COUNT(*) n FROM supply_offers WHERE request_id=? AND status<>'DRAFT'",[$id])[0]['n']??0);$p=request_payload($input);$version=(int)$r['current_version']+1;db()->prepare('UPDATE marketplace_requests SET equipment_type_id=?,category_id=?,subcategory_id=?,title=?,description=?,intent=?,quantity_required=?,required_location_id=?,required_from=?,required_until=?,response_deadline=?,visibility=?,alternatives_accepted=?,core_specifications=?,required_documents=?,oem_preference=?,model_preference=?,current_version=? WHERE id=?')->execute([$p['equipment_type_id'],$p['category_id'],$p['subcategory_id'],$p['title'],$p['description'],$p['intent'],$p['quantity_required'],$p['required_location_id'],$p['required_from'],$p['required_until'],$p['response_deadline'],$p['visibility'],$p['alternatives_accepted'],$p['core_specifications'],$p['required_documents'],$p['oem_preference'],$p['model_preference'],$version,$id]);request_save_requirements($id,json_decode($p['core_specifications'],true));$fresh=rows('SELECT * FROM marketplace_requests WHERE id=?',[$id])[0];db()->prepare('INSERT INTO marketplace_request_versions(id,request_id,version_number,snapshot,change_reason,created_by) VALUES(?,?,?,?,?,?)')->execute([uuid(),$id,$version,json_encode(request_snapshot($fresh),JSON_THROW_ON_ERROR),$responses?'Material edit after supplier responses began':null,$user['id']]);request_event($id,$user,'UPDATED',['version'=>$version,'responses_present'=>(bool)$responses]);}
function request_publish(array $user,string $id):void{$r=request_owned($user,$id,true);if($r['status']!=='DRAFT')throw new DomainException('Only a draft request can be published.',409);if($r['response_deadline']<=gmdate('Y-m-d H:i:s'))throw new DomainException('Extend the response deadline before publishing.',409);db()->prepare("UPDATE marketplace_requests SET status='OPEN',published_at=UTC_TIMESTAMP() WHERE id=?")->execute([$id]);request_event($id,$user,'PUBLISHED');}
function request_extend(array $user,string $id,string $deadline):void{$r=request_owned($user,$id,true);if(!in_array($r['status'],['OPEN','RESPONSES_RECEIVED','EXPIRED'],true))throw new DomainException('This request cannot be extended.',409);$deadline=str_replace('T',' ',$deadline).':00';if($deadline<=gmdate('Y-m-d H:i:s'))throw new DomainException('New deadline must be in the future.',422);$status=(int)(rows("SELECT COUNT(*) n FROM supply_offers WHERE request_id=? AND status IN ('SUBMITTED','VIEWED')",[$id])[0]['n'])?'RESPONSES_RECEIVED':'OPEN';db()->prepare('UPDATE marketplace_requests SET response_deadline=?,status=?,expired_at=NULL WHERE id=?')->execute([$deadline,$status,$id]);request_event($id,$user,'DEADLINE_EXTENDED',['deadline'=>$deadline]);}
function request_close(array $user,string $id,string $status):void{request_owned($user,$id,true);if(!in_array($status,['CLOSED','CANCELLED'],true))throw new DomainException('Invalid request closure.',422);db()->prepare('UPDATE marketplace_requests SET status=? WHERE id=?')->execute([$status,$id]);request_event($id,$user,$status);}

function supply_offer(array $user,string $id,bool $lock=false):array{$row=rows("SELECT o.*,r.organization_id requester_organization_id,r.title request_title,r.intent,r.status request_status,r.required_from,r.required_until,r.quantity_required,v.id version_id,v.commercial_terms,v.technical_response,v.deviations,v.validity_until,e.name equipment_name,l.title listing_title,so.name supplier_name,ro.name requester_name FROM supply_offers o JOIN marketplace_requests r ON r.id=o.request_id JOIN supply_offer_versions v ON v.supply_offer_id=o.id AND v.version_number=o.current_version JOIN equipment e ON e.id=o.equipment_id LEFT JOIN marketplace_listings l ON l.id=o.marketplace_listing_id JOIN owners so ON so.id=o.supplier_organization_id JOIN owners ro ON ro.id=r.organization_id WHERE o.id=?".($lock?' FOR UPDATE':''),[$id])[0]??null;if(!$row)throw new DomainException('Supply offer not found.',404);if(!in_array($user['owner_id'],[$row['supplier_organization_id'],$row['requester_organization_id']],true))throw new DomainException('You do not have access to this supply offer.',403);if(!request_manager($user)&&$row['created_by']!==$user['id'])throw new DomainException('Your role cannot manage this offer.',403);return $row;}
function supply_terms(array $input,array $request):array{$amount=marketplace_number($input,'amount');if($amount<=0)throw new DomainException('Enter a positive rate or purchase price.',422);$currency=strtoupper(marketplace_text($input,'currency',3,true));$basis=marketplace_enum($input,'pricing_basis',['HOURLY','DAILY','WEEKLY','MONTHLY','PROJECT','FIXED'],$request['intent']==='PURCHASE'?'FIXED':'DAILY');return ['amount'=>$amount,'currency'=>$currency,'pricing_basis'=>$basis,'available_from'=>marketplace_text($input,'available_from',10,true),'available_until'=>marketplace_text($input,'available_until',10),'mobilization_delivery'=>marketplace_text($input,'mobilization_delivery',5000),'demobilization'=>marketplace_text($input,'demobilization',5000),'security_deposit'=>marketplace_number($input,'security_deposit'),'operator_terms'=>marketplace_text($input,'operator_terms',2000),'maintenance_responsibility'=>marketplace_text($input,'maintenance_responsibility',2000),'insurance_requirements'=>marketplace_text($input,'insurance_requirements',2000),'notes'=>marketplace_text($input,'notes',5000)];}
function supply_offer_save(array $user,array $input,bool $submit):string{if(!request_manager($user))throw new DomainException('Your role cannot submit supply offers.',403);$request=request_record($user,marketplace_text($input,'request_id',36,true));if($request['organization_id']===$user['owner_id'])throw new DomainException('You cannot respond to your own request.',409);if(!in_array($request['status'],['OPEN','RESPONSES_RECEIVED'],true)||$request['response_deadline']<=gmdate('Y-m-d H:i:s'))throw new DomainException('This request is not accepting responses.',409);$equipment=rows('SELECT * FROM equipment WHERE id=? AND owner_id=? AND archived_at IS NULL',[marketplace_text($input,'equipment_id',36,true),$user['owner_id']])[0]??null;if(!$equipment)throw new DomainException('Choose equipment owned by your organization.',422);$listing=marketplace_text($input,'marketplace_listing_id',36);if($listing&&!rows('SELECT 1 FROM marketplace_listings WHERE id=? AND asset_id=? AND organization_id=?',[$listing,$equipment['id'],$user['owner_id']]))throw new DomainException('The selected listing does not match this equipment.',422);$quantity=max(1,(int)($input['quantity_offered']??1));$terms=supply_terms($input,$request);$id=uuid();$version=uuid();$validity=str_replace('T',' ',marketplace_text($input,'validity_until',16,true)).':00';if($validity<=gmdate('Y-m-d H:i:s'))throw new DomainException('Offer validity must be in the future.',422);db()->prepare('INSERT INTO supply_offers(id,request_id,supplier_organization_id,created_by,equipment_id,marketplace_listing_id,quantity_offered,status,submitted_at) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$id,$request['id'],$user['owner_id'],$user['id'],$equipment['id'],$listing?:null,$quantity,$submit?'SUBMITTED':'DRAFT',$submit?gmdate('Y-m-d H:i:s'):null]);db()->prepare('INSERT INTO supply_offer_versions(id,supply_offer_id,version_number,commercial_terms,technical_response,deviations,validity_until,created_by) VALUES(?,?,1,?,?,?,?,?)')->execute([$version,$id,json_encode($terms,JSON_THROW_ON_ERROR),json_encode(request_specs((string)($input['technical_response']??'')),JSON_THROW_ON_ERROR),json_encode(request_specs((string)($input['deviations']??'')),JSON_THROW_ON_ERROR),$validity,$user['id']]);supply_document_save($version,$input['_file']??[]);if($submit){db()->prepare("UPDATE marketplace_requests SET status='RESPONSES_RECEIVED' WHERE id=? AND status='OPEN'")->execute([$request['id']]);marketplace_notify_organization($request['organization_id'],'REQUEST_RESPONSE','request',$request['id'],'New response to equipment request',$request['title'],$user['id']);}request_event($request['id'],$user,$submit?'OFFER_SUBMITTED':'OFFER_DRAFTED',['supply_offer_id'=>$id,'version'=>1]);return $id;}
function supply_document_save(string $version,array $file):void{if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)return;$mime=(new finfo(FILEINFO_MIME_TYPE))->file((string)$file['tmp_name']);$allowed=['application/pdf','image/jpeg','image/png','application/vnd.openxmlformats-officedocument.wordprocessingml.document'];if(!in_array($mime,$allowed,true)||($file['size']??0)>10*1024*1024)throw new DomainException('Upload a PDF, DOCX, JPEG or PNG up to 10 MB.',422);db()->prepare('INSERT INTO supply_offer_documents(id,supply_offer_version_id,file_name,mime_type,file_size,file_data) VALUES(?,?,?,?,?,?)')->execute([uuid(),$version,substr(basename((string)$file['name']),0,255),$mime,$file['size'],file_get_contents($file['tmp_name'])]);}
function supply_offer_submit(array $user,string $id):void{$offer=supply_offer($user,$id,true);if($offer['supplier_organization_id']!==$user['owner_id']||$offer['status']!=='DRAFT')throw new DomainException('This draft cannot be submitted.',409);if($offer['validity_until']<=gmdate('Y-m-d H:i:s'))throw new DomainException('Offer validity has expired.',409);db()->prepare("UPDATE supply_offers SET status='SUBMITTED',submitted_at=UTC_TIMESTAMP() WHERE id=?")->execute([$id]);db()->prepare("UPDATE marketplace_requests SET status='RESPONSES_RECEIVED' WHERE id=? AND status='OPEN'")->execute([$offer['request_id']]);request_event($offer['request_id'],$user,'OFFER_SUBMITTED',['supply_offer_id'=>$id,'version'=>$offer['current_version']]);}
function supply_offer_revise(array $user,string $id,array $input):void{$offer=supply_offer($user,$id,true);if($offer['supplier_organization_id']!==$user['owner_id']||!in_array($offer['status'],['SUBMITTED','VIEWED'],true))throw new DomainException('This offer cannot be revised.',409);$request=request_record($user,$offer['request_id']);$terms=supply_terms($input,$request);$number=(int)$offer['current_version']+1;$version=uuid();$validity=str_replace('T',' ',marketplace_text($input,'validity_until',16,true)).':00';db()->prepare('INSERT INTO supply_offer_versions(id,supply_offer_id,version_number,commercial_terms,technical_response,deviations,validity_until,created_by) VALUES(?,?,?,?,?,?,?,?)')->execute([$version,$id,$number,json_encode($terms,JSON_THROW_ON_ERROR),json_encode(request_specs((string)($input['technical_response']??'')),JSON_THROW_ON_ERROR),json_encode(request_specs((string)($input['deviations']??'')),JSON_THROW_ON_ERROR),$validity,$user['id']]);db()->prepare("UPDATE supply_offers SET current_version=?,status='SUBMITTED',submitted_at=UTC_TIMESTAMP() WHERE id=?")->execute([$number,$id]);supply_document_save($version,$input['_file']??[]);request_event($offer['request_id'],$user,'OFFER_REVISED',['supply_offer_id'=>$id,'version'=>$number]);}
function supply_offer_message(array $user,string $id,string $message):void{$offer=supply_offer($user,$id);db()->prepare('INSERT INTO request_messages(id,request_id,supply_offer_id,sender_user_id,message_text) VALUES(?,?,?,?,?)')->execute([uuid(),$offer['request_id'],$id,$user['id'],mb_substr(trim($message),0,5000)]);$other=$user['owner_id']===$offer['supplier_organization_id']?$offer['requester_organization_id']:$offer['supplier_organization_id'];marketplace_notify_organization($other,'REQUEST_CLARIFICATION','supply_offer',$id,'Request offer clarification',$offer['request_title'],$user['id']);request_event($offer['request_id'],$user,'CLARIFICATION_SENT',['supply_offer_id'=>$id]);}
function supply_offer_not_select(array $user,string $id):void{$offer=supply_offer($user,$id,true);if($offer['requester_organization_id']!==$user['owner_id']||!request_manager($user))throw new DomainException('Only the requester can make this decision.',403);db()->prepare("UPDATE supply_offers SET status='NOT_SELECTED' WHERE id=? AND status IN ('SUBMITTED','VIEWED')")->execute([$id]);request_event($offer['request_id'],$user,'OFFER_NOT_SELECTED',['supply_offer_id'=>$id]);}
function supply_offer_withdraw(array $user,string $id):void{$offer=supply_offer($user,$id,true);if($offer['supplier_organization_id']!==$user['owner_id'])throw new DomainException('Only the supplier can withdraw this offer.',403);db()->prepare("UPDATE supply_offers SET status='WITHDRAWN' WHERE id=? AND status IN ('DRAFT','SUBMITTED','VIEWED')")->execute([$id]);request_event($offer['request_id'],$user,'OFFER_WITHDRAWN',['supply_offer_id'=>$id]);}
function request_award_offer(array $user,string $offerId,string $type):string{$offer=supply_offer($user,$offerId,true);$request=request_owned($user,$offer['request_id'],true);if(!in_array($offer['status'],['SUBMITTED','VIEWED'],true)||$offer['validity_until']<=gmdate('Y-m-d H:i:s'))throw new DomainException('This supply offer is no longer awardable.',409);$type=marketplace_enum(['type'=>$type],'type',['LEASE','PURCHASE']);if($request['intent']!=='EITHER'&&$request['intent']!==$type)throw new DomainException('Award type must match the request intent.',409);$terms=json_decode($offer['commercial_terms'],true,64,JSON_THROW_ON_ERROR);$award=uuid();db()->prepare('INSERT INTO request_awards(id,request_id,supply_offer_id,supply_offer_version_id,awarded_quantity,transaction_type,awarded_by) VALUES(?,?,?,?,?,?,?)')->execute([$award,$request['id'],$offerId,$offer['version_id'],min((int)$offer['quantity_offered'],(int)$request['quantity_required']),$type,$user['id']]);$transaction=uuid();$transactionType=$type==='PURCHASE'?'SALE':'LEASE';db()->prepare('INSERT INTO marketplace_transactions(id,transaction_type,listing_id,asset_id,request_award_id,supplier_organization_id,customer_organization_id,gross_value,currency,frozen_terms) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$transaction,$transactionType,$offer['marketplace_listing_id']?:null,$offer['equipment_id'],$award,$offer['supplier_organization_id'],$request['organization_id'],$terms['amount'],$terms['currency'],json_encode(['request'=>request_snapshot($request),'offer'=>$terms,'technical_response'=>json_decode($offer['technical_response'],true),'deviations'=>json_decode($offer['deviations'],true)],JSON_THROW_ON_ERROR)]);db()->prepare('UPDATE request_awards SET transaction_id=? WHERE id=?')->execute([$transaction,$award]);if($type==='LEASE'){$lease=uuid();$end=$request['required_until'];db()->prepare("INSERT INTO request_asset_reservations(id,award_id,equipment_id,quantity,start_date,end_date,status) VALUES(?,?,?,?,?,?,'CONFIRMED')")->execute([uuid(),$award,$offer['equipment_id'],min((int)$offer['quantity_offered'],(int)$request['quantity_required']),$request['required_from'],$end]);db()->prepare('INSERT INTO marketplace_leases(id,transaction_id,asset_id,lessor_organization_id,lessee_organization_id,contracted_start,contracted_end,rate,rate_basis) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$lease,$transaction,$offer['equipment_id'],$offer['supplier_organization_id'],$request['organization_id'],$request['required_from'],$end,$terms['amount'],in_array($terms['pricing_basis'],['HOURLY','DAILY','WEEKLY','MONTHLY','PROJECT'],true)?$terms['pricing_basis']:'PROJECT']);}db()->prepare("INSERT INTO marketplace_payments(id,transaction_id,idempotency_key,amount,currency,payment_type,status,due_at) VALUES(?,?,?,?,?,'FULL','PENDING',DATE_ADD(UTC_TIMESTAMP(),INTERVAL 7 DAY))")->execute([uuid(),$transaction,'request-award-'.$award,$terms['amount'],$terms['currency']]);db()->prepare("INSERT INTO marketplace_escrow_records(id,transaction_id,secured_amount,currency,status) VALUES(?,?,?,?,'PENDING')")->execute([uuid(),$transaction,$terms['amount'],$terms['currency']]);$eventData=json_encode(['request_id'=>$request['id'],'supply_offer_id'=>$offerId,'award_id'=>$award],JSON_THROW_ON_ERROR);db()->prepare("INSERT INTO marketplace_transaction_activity(transaction_id,actor_user_id,actor_organization_id,event_type,event_data) VALUES(?,?,?,'TRANSACTION_CREATED',?)")->execute([$transaction,$user['id'],$user['owner_id'],$eventData]);$hash=hash('sha256',$transaction.'|1|'.$user['id'].'|TRANSACTION_CREATED|'.$eventData.'|');db()->prepare("INSERT INTO marketplace_commercial_audit(transaction_id,sequence_number,actor_user_id,event_type,event_data,event_hash) VALUES(?,1,?,'TRANSACTION_CREATED',?,?)")->execute([$transaction,$user['id'],$eventData,$hash]);db()->prepare("UPDATE supply_offers SET status='ACCEPTED',accepted_version_id=? WHERE id=?")->execute([$offer['version_id'],$offerId]);db()->prepare("UPDATE supply_offers SET status='NOT_SELECTED' WHERE request_id=? AND id<>? AND status IN ('SUBMITTED','VIEWED')")->execute([$request['id'],$offerId]);db()->prepare("UPDATE marketplace_requests SET status='AWARDED' WHERE id=?")->execute([$request['id']]);marketplace_notify_organization($offer['supplier_organization_id'],'REQUEST_AWARDED','transaction',$transaction,'Supply offer accepted',$request['title'],$user['id']);request_event($request['id'],$user,'AWARDED',['award_id'=>$award,'transaction_id'=>$transaction,'supply_offer_id'=>$offerId]);return $transaction;}
